ee:message.ee:set-payload:
 %dw 2.0
output application/java
---
[{
    EBS_External_ID__c: vars.externalId,
    LastName: vars.requestBody.lastName,

    (FirstName: vars.requestBody.firstName)
        if (vars.requestBody.firstName != null),

    (Email: vars.requestBody.email)
        if (vars.requestBody.email != null),

    (Phone: vars.requestBody.phone)
        if (vars.requestBody.phone != null),

    (MailingCity: vars.requestBody.city)
        if (vars.requestBody.city != null),

    (MailingCountry: vars.requestBody.country)
        if (vars.requestBody.country != null),

    (MailingState: vars.requestBody.state)
        if (
            vars.requestBody.state != null
            and vars.requestBody.country != null
        ),

    (MailingPostalCode: vars.requestBody.postalCode)
        if (vars.requestBody.postalCode != null)
}]

%dw 2.0
output application/json

var result = vars.updateResult default {}
var items = result.items default result.Items default []
var item = items[0] default {}

var operationSuccess =
    (result.successful default result.Successful default false) as Boolean

var itemSuccess =
    if (isEmpty(items))
        operationSuccess
    else
        (item.successful default item.Successful default false) as Boolean

var success = operationSuccess and itemSuccess

---
{
    success: success,
    message:
        if (success)
            "Contact updated successfully"
        else
            "Salesforce did not confirm a successful Contact update",
    contactId: item.id default item.Id default vars.contactId,
    errors:
        if (success)
            []
        else
            [{
                statusCode: item.statusCode default item.StatusCode default null,
                message: item.message
                    default item.Message
                    default "Salesforce returned an unsuccessful update result"
            }]
}

%dw 2.0
output application/json

var result = vars.deleteResult default {}
var items = result.Items default result.items default []
var item = items[0] default {}

var operationSuccess =
    (result.Successful default result.successful default false) as Boolean

var itemSuccess =
    (item.Successful default item.successful default false) as Boolean

var success = operationSuccess and itemSuccess

---
{
    success: success,
    message:
        if (success)
            "Contact deleted successfully"
        else
            "Salesforce did not confirm a successful Contact deletion",
    contactId: item.Id default item.id default vars.contactId,
    errors:
        if (success)
            []
        else
            [{
                statusCode: item.StatusCode default item.statusCode default null,
                message: item.Message
                    default item.message
                    default "Salesforce returned an unsuccessful delete result"
            }]
}
